-- Compact S/T catalog keyed by Prod. Material (GH96 code).
-- Only the current snapshot and actual price changes are retained; raw ERP rows stay in Google Sheets.
create table if not exists public.st_products (
  product_code text primary key check (product_code ~ '^GH96-[A-Z0-9]+$'),
  model_name text not null,
  product_type text not null check (product_type in ('Smart','Tab')),
  labor_cost numeric(14,3) not null check (labor_cost > 0),
  current_price numeric(14,2) not null check (current_price > 1000),
  current_st numeric(14,6) not null check (current_st >= 0),
  latest_gap_st numeric(14,6) not null default 0,
  change_count integer not null default 0 check (change_count >= 0),
  last_change_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.st_price_history (
  id bigint generated always as identity primary key,
  product_code text not null references public.st_products(product_code) on delete cascade,
  old_price numeric(14,2),
  new_price numeric(14,2) not null,
  old_st numeric(14,6),
  new_st numeric(14,6) not null,
  gap_st numeric(14,6) not null default 0,
  change_date date not null default current_date,
  reason text,
  voc_code text,
  source text not null default 'ERP' check (source in ('ERP','VOC')),
  created_at timestamptz not null default now()
);

create index if not exists st_price_history_product_date_idx
  on public.st_price_history(product_code,change_date desc,id desc);

alter table public.st_products enable row level security;
alter table public.st_price_history enable row level security;
revoke all on public.st_products from anon,authenticated;
revoke all on public.st_price_history from anon,authenticated;

