insert into public.st_products(product_code,model_name,product_type,labor_cost,current_price,current_st,last_change_at,updated_at)
select product_code,model_name,product_type,labor_cost,current_price,round(current_price/labor_cost,6),
       '2026-10-14 00:00:00+07'::timestamptz,'2026-10-14 00:00:00+07'::timestamptz
from seed
where current_price > 1000
on conflict (product_code) do nothing;

insert into public.st_price_history(product_code,new_price,new_st,gap_st,change_date,source)
select p.product_code,p.current_price,p.current_st,0,'2026-10-14'::date,'ERP'
from public.st_products p
where not exists(select 1 from public.st_price_history h where h.product_code=p.product_code);

create or replace function public.get_st_catalog()
returns table(
  product_code text,
  model_name text,
  product_type text,
  labor_cost numeric,
  current_price numeric,
  current_st numeric,
  latest_gap_st numeric,
  change_count integer,
  last_change_at timestamptz
)
language sql stable security definer set search_path=pg_catalog,public as $$
  select p.product_code,p.model_name,p.product_type,p.labor_cost,p.current_price,p.current_st,
         p.latest_gap_st,p.change_count,p.last_change_at
  from public.st_products p
  where p.current_price > 1000
  order by p.model_name,p.product_code;
$$;

create or replace function public.get_st_history(p_product_code text)
returns table(
  id bigint,
  old_price numeric,
  new_price numeric,
  old_st numeric,
  new_st numeric,
  gap_st numeric,
  change_date date,
  reason text,
  voc_code text,
  source text,
  created_at timestamptz
)
language sql stable security definer set search_path=pg_catalog,public as $$
  select h.id,h.old_price,h.new_price,h.old_st,h.new_st,h.gap_st,h.change_date,
         h.reason,h.voc_code,h.source,h.created_at
  from public.st_price_history h
  where h.product_code=upper(trim(p_product_code))
  order by h.change_date desc,h.id desc
  limit 100;
$$;

create or replace function public.apply_st_voc_batch(p_rows jsonb)
returns jsonb
language plpgsql security definer set search_path=pg_catalog,public as $$
declare
  item jsonb;
  code text;
  price numeric;
  effective_date date;
  product public.st_products%rowtype;
  next_st numeric;
  updated_count integer := 0;
  skipped_count integer := 0;
begin
  if not public.is_admin() then
    raise exception 'admin_required_to_import_voc' using errcode='42501';
  end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 500 then
    raise exception 'voc_rows_must_be_an_array_of_at_most_500_items' using errcode='22023';
  end if;
  for item in select value from jsonb_array_elements(p_rows)
  loop
    code := upper(trim(item->>'product_code'));
    begin price := (item->>'new_price')::numeric; exception when others then price := null; end;
    begin effective_date := coalesce((item->>'change_date')::date,current_date); exception when others then effective_date := current_date; end;
    select * into product from public.st_products where product_code=code for update;
    if not found or price is null or price <= 1000 or price=product.current_price then
      skipped_count := skipped_count + 1;
      continue;
    end if;
    next_st := round(price/product.labor_cost,6);
    insert into public.st_price_history(product_code,old_price,new_price,old_st,new_st,gap_st,change_date,reason,voc_code,source)
    values(code,product.current_price,price,product.current_st,next_st,next_st-product.current_st,effective_date,
           nullif(trim(item->>'reason'),''),nullif(trim(item->>'voc_code'),''),'VOC');
    update public.st_products
    set current_price=price,current_st=next_st,latest_gap_st=next_st-product.current_st,
        change_count=product.change_count+1,last_change_at=effective_date::timestamptz,updated_at=now()
    where product_code=code;
    updated_count := updated_count + 1;
  end loop;
  return jsonb_build_object('updated',updated_count,'skipped',skipped_count);
end;
$$;

create or replace function public.sync_st_erp_snapshot(p_rows jsonb)
returns jsonb
language plpgsql security definer set search_path=pg_catalog,public as $$
declare
  item jsonb;
  code text;
  price numeric;
  product public.st_products%rowtype;
  next_st numeric;
  updated_count integer := 0;
  skipped_count integer := 0;
begin
  if not public.is_admin() then
    raise exception 'admin_required_to_sync_st' using errcode='42501';
  end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 1000 then
    raise exception 'erp_rows_must_be_an_array_of_at_most_1000_items' using errcode='22023';
  end if;
  for item in select value from jsonb_array_elements(p_rows)
  loop
    code := upper(trim(item->>'product_code'));
    begin price := (item->>'net_price')::numeric; exception when others then price := null; end;
    select * into product from public.st_products where product_code=code for update;
    if not found or price is null or price <= 1000 or price=product.current_price then
      skipped_count := skipped_count + 1;
      continue;
    end if;
    next_st := round(price/product.labor_cost,6);
    insert into public.st_price_history(product_code,old_price,new_price,old_st,new_st,gap_st,change_date,source)
    values(code,product.current_price,price,product.current_st,next_st,next_st-product.current_st,current_date,'ERP');
    update public.st_products
    set current_price=price,current_st=next_st,latest_gap_st=next_st-product.current_st,
        change_count=product.change_count+1,last_change_at=now(),updated_at=now()
    where product_code=code;
    updated_count := updated_count + 1;
  end loop;
  return jsonb_build_object('updated',updated_count,'skipped',skipped_count);
end;
$$;

revoke all on function public.get_st_catalog() from public;
revoke all on function public.get_st_history(text) from public;
revoke all on function public.apply_st_voc_batch(jsonb) from public;
revoke all on function public.sync_st_erp_snapshot(jsonb) from public;
grant execute on function public.get_st_catalog() to anon,authenticated;
grant execute on function public.get_st_history(text) to anon,authenticated;
grant execute on function public.apply_st_voc_batch(jsonb) to authenticated;
grant execute on function public.sync_st_erp_snapshot(jsonb) to authenticated;

update public.workspace_settings
set visible_categories=case
  when visible_categories @> '["st-info"]'::jsonb then visible_categories
  else visible_categories || '["st-info"]'::jsonb
end,updated_at=now()
where singleton=true;

create or replace function public.set_workspace_visible_categories(p_visible_categories jsonb)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
begin
  if not public.is_admin() then
    raise exception 'admin_required_to_manage_categories' using errcode='42501';
  end if;
  if jsonb_typeof(p_visible_categories) <> 'array' or jsonb_array_length(p_visible_categories)=0 then
    raise exception 'visible_categories_must_be_a_non_empty_array' using errcode='22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements_text(p_visible_categories) value
    where value not in ('lob-summary','overview','processes','jigs','st-info')
  ) then
    raise exception 'invalid_visible_category' using errcode='22023';
  end if;
  insert into public.workspace_settings(singleton,visible_categories,updated_at)
  values (true,p_visible_categories,now())
  on conflict (singleton) do update set visible_categories=excluded.visible_categories,updated_at=excluded.updated_at;
  return p_visible_categories;
end;
$$;
revoke all on function public.set_workspace_visible_categories(jsonb) from public;
grant execute on function public.set_workspace_visible_categories(jsonb) to authenticated;

